function isBalanced(s) {
  const stack = [];
  for (const ch of s) {
    if (ch === '(') stack.push(ch);
    else {
      if (stack.length === 0) return false;
      stack.pop();
    }
  }
  return stack.length === 0;
}
console.log(isBalanced('(()())'));
console.log(isBalanced('(()'))

